"""Authoritative run ledger: every count in the paper comes from here (docs/RUN_LEDGER.md, generated, do not edit).

Definitions used everywhere:
  trace         one generated packet sequence (operating point + seed)
  group         one (operating point, seed) pair
  run           one scheduler simulated on one trace (one row of a runs.csv)
  paired group  a group in which several schedulers ran on the same trace (one trace digest)
Usage: python tools/run_ledger.py [--check]   (--check exits non-zero if docs/RUN_LEDGER.md is stale)
"""
import json
import sys
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
MAIN = ["E1", "E2", "E3", "E4", "E5", "E6", "E7", "E8"]
FURTHER = ["E1D", "E1V", "E9", "E9C", "E10", "E11", "E12", "E14", "E15", "E19", "E19H", "E20", "E20B", "E21", "ES"]
TUNING = ["TUNE", "DEVD", "E14TUNE", "E19TUNE"]


def stats(exp):
    path = ROOT / "results" / exp / "runs.csv"
    if not path.exists():
        return None
    d = pd.read_csv(path)
    g = d.groupby(["point", "seed"])
    per_group = g.size()
    paired = per_group[per_group > 1]
    if exp == "E6":      # one run per knob setting; traces repeat across settings of the same load
        key = d.point.str.split("load=").str[1]
        digests = d.groupby([key, "seed"]).trace.nunique()
    else:
        digests = g.trace.nunique()
    assert (digests == 1).all(), f"{exp}: a group or shared trace has more than one trace digest"
    return {"exp": exp, "runs": len(d), "points": d.point.nunique(), "seeds": d.seed.nunique(),
            "schedulers": d.scheduler.nunique(), "groups": len(per_group), "paired_groups": len(paired),
            "runs_in_paired_groups": int(paired.sum()), "unpaired_runs": int((per_group == 1).sum()),
            "distinct_traces": int(d.trace.nunique())}


def build():
    rows = {e: stats(e) for e in MAIN + FURTHER + TUNING}
    rows = {e: r for e, r in rows.items() if r}
    cat = lambda names: sum(rows[e]["runs"] for e in names if e in rows)
    main, further, tuning = cat(MAIN), cat(FURTHER), cat(TUNING)
    kernel = sum(len(pd.read_csv(p)) // 3 for p in sorted((ROOT / "results").glob("E16*/*/summary.csv")))
    replay = sum(len(pd.read_csv(p)) for p in [ROOT / "results/E17/runs.csv", *sorted((ROOT / "results/E17b").glob("*/runs.csv")), *sorted((ROOT / "results/E17c").glob("runs.csv"))])
    archived = sum(len(pd.read_csv(p)) for p in (ROOT / "results").glob("_*/**/runs.csv"))
    return rows, {"main": main, "further": further, "tuning": tuning, "simulator_total": main + further + tuning,
                  "kernel_runs": kernel, "replay_runs": replay, "archived": archived,
                  "main_paired_groups": sum(rows[e]["paired_groups"] for e in MAIN if e in rows),
                  "main_paired_runs": sum(rows[e]["runs_in_paired_groups"] for e in MAIN if e in rows),
                  "main_single_runs": sum(rows[e]["unpaired_runs"] for e in MAIN if e in rows),
                  "main_groups": sum(rows[e]["groups"] for e in MAIN if e in rows)}


def render(rows, t):
    out = ["# Run ledger (generated by tools/run_ledger.py; do not edit)", "",
           "Definitions: a *trace* is one generated packet sequence; a *group* is one (operating point, seed) pair; a *run* is "
           "one scheduler simulated on one trace; a *paired group* is a group in which several schedulers ran on the same trace "
           "(one trace digest, checked). Kernel and replay runs are separate populations and are **not** in the simulator total.", "",
           "| experiment | category | runs | points | seeds | schedulers | groups | paired groups | runs in paired groups | single-scheduler runs | distinct traces |",
           "|---|---|---|---|---|---|---|---|---|---|---|"]
    for names, label in ((MAIN, "main"), (FURTHER, "further"), (TUNING, "tuning")):
        for e in names:
            if e in rows:
                r = rows[e]
                out.append(f"| {e} | {label} | {r['runs']} | {r['points']} | {r['seeds']} | {r['schedulers']} | {r['groups']} | "
                           f"{r['paired_groups']} | {r['runs_in_paired_groups']} | {r['unpaired_runs']} | {r['distinct_traces']} |")
    out += ["", "| quantity | value |", "|---|---|",
            f"| main matrix runs (E1-E8) | {t['main']:,} |",
            f"| of which in eight-scheduler paired groups ({t['main_paired_groups']} groups) | {t['main_paired_runs']:,} |",
            f"| of which single-scheduler sensitivity runs (E6) | {t['main_single_runs']:,} |",
            f"| (point, seed) groups in the main matrix | {t['main_groups']:,} |",
            f"| further reported arms | {t['further']:,} |", f"| tuning on development seeds | {t['tuning']:,} |",
            f"| **simulator runs in total** | **{t['simulator_total']:,}** |",
            f"| kernel runs (E16, E16b), not in the total | {t['kernel_runs']} |",
            f"| replay runs (E17, E17b, E17c), not in the total | {t['replay_runs']} |",
            f"| archived runs superseded by fixes, not reported | {t['archived']:,} |"]
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    rows, totals = build()
    text = render(rows, totals)
    path = ROOT / "docs" / "RUN_LEDGER.md"
    if "--check" in sys.argv:
        stale = not path.exists() or path.read_text(encoding="utf-8").replace("\r\n", "\n") != text
        print("RUN_LEDGER.md is", "STALE" if stale else "current")
        sys.exit(1 if stale else 0)
    path.write_text(text, encoding="utf-8")
    (ROOT / "docs" / "run_ledger.json").write_text(json.dumps(totals, indent=1), encoding="utf-8")
    print(text)
